solution.solution.cpp:
#include <cctype>
#include <string>
#include <vector>

constexpr int LB_ERR = -1;

namespace
{
    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }
}

class ListBox
{
public:
    explicit ListBox(bool sorted) : m_sorted{ sorted } {}

    int addString(const std::string& s)
    {
        int at{ getCount() };
        if (m_sorted)
        {
            const std::string key{ lower(s) };
            at = 0;
            while (at < getCount() && lower(m_items[static_cast<std::size_t>(at)]) <= key) ++at;
        }
        return insertAt(at, s);
    }

    int insertString(int index, const std::string& s)
    {
        if (index == -1) index = getCount();
        if (index < 0 || index > getCount()) return LB_ERR;
        return insertAt(index, s);
    }

    int deleteString(int index)
    {
        if (index < 0 || index >= getCount()) return LB_ERR;
        m_items.erase(m_items.begin() + index);
        if (m_sel == index) m_sel = LB_ERR;
        else if (m_sel > index) --m_sel;
        return getCount();
    }

    int getCount() const { return static_cast<int>(m_items.size()); }
    int getCurSel() const { return m_sel; }

    int setCurSel(int index)
    {
        if (index == -1) { m_sel = LB_ERR; return LB_ERR; }
        if (index < 0 || index >= getCount()) return LB_ERR;
        m_sel = index;
        return index;
    }

    std::string getText(int index) const
    {
        return index >= 0 && index < getCount() ? m_items[static_cast<std::size_t>(index)] : "";
    }

    int findString(int start, const std::string& prefix) const
    {
        const int n{ getCount() };
        if (n == 0) return LB_ERR;
        if (start < -1 || start >= n) start = -1;
        const std::string p{ lower(prefix) };
        for (int k{ 1 }; k <= n; ++k)
        {
            const int i{ (start + k) % n };
            if (lower(m_items[static_cast<std::size_t>(i)]).rfind(p, 0) == 0) return i;
        }
        return LB_ERR;
    }

private:
    int insertAt(int at, const std::string& s)
    {
        m_items.insert(m_items.begin() + at, s);
        if (m_sel != LB_ERR && m_sel >= at) ++m_sel;
        return at;
    }

    bool m_sorted;
    std::vector<std::string> m_items;
    int m_sel{ LB_ERR };
};

unitTests:
TEST("unsorted") { ListBox l{ false }; CHECK_EQ(l.addString("pear"), 0); CHECK_EQ(l.addString("apple"), 1); CHECK_EQ(l.insertString(0, "fig"), 0); CHECK_EQ(l.insertString(-1, "kiwi"), 3); CHECK_EQ(l.getText(1), std::string("pear")); CHECK_EQ(l.insertString(9, "x"), LB_ERR); }
TEST("sorted, case-insensitive") {
    ListBox l{ true }; l.addString("pear"); l.addString("Apple"); l.addString("banana"); CHECK_EQ(l.addString("apple"), 1);
    CHECK_EQ(l.getText(0), std::string("Apple")); CHECK_EQ(l.getText(1), std::string("apple")); CHECK_EQ(l.getText(3), std::string("pear"));
    CHECK_EQ(l.insertString(0, "zebra"), 0);
}
TEST("selection follows the items") {
    ListBox l{ false }; for (const char* s : { "a", "b", "c", "d" }) l.addString(s);
    CHECK_EQ(l.getCurSel(), LB_ERR); CHECK_EQ(l.setCurSel(2), 2); l.insertString(0, "z"); CHECK_EQ(l.getCurSel(), 3);
    CHECK_EQ(l.deleteString(0), 4); CHECK_EQ(l.getCurSel(), 2); CHECK_EQ(l.deleteString(2), 3); CHECK_EQ(l.getCurSel(), LB_ERR);
    CHECK_EQ(l.setCurSel(7), LB_ERR); CHECK_EQ(l.setCurSel(1), 1); CHECK_EQ(l.setCurSel(-1), LB_ERR); CHECK_EQ(l.getCurSel(), LB_ERR); CHECK_EQ(l.deleteString(5), LB_ERR);
}
TEST("finding by prefix") {
    ListBox l{ false }; for (const char* s : { "Granite", "Basalt", "gneiss", "Slate", "Gabbro" }) l.addString(s);
    CHECK_EQ(l.findString(-1, "g"), 0); CHECK_EQ(l.findString(0, "G"), 2); CHECK_EQ(l.findString(2, "g"), 4); CHECK_EQ(l.findString(4, "g"), 0);
    CHECK_EQ(l.findString(-1, "SL"), 3); CHECK_EQ(l.findString(-1, "marble"), LB_ERR); CHECK_EQ(l.findString(3, "slate"), 3);
    CHECK_EQ(ListBox{ false }.findString(-1, "a"), LB_ERR);
}

